"use client";
import {useCallback,useEffect,useMemo,useState} from "react";
import {getSupabase} from "@/lib/supabase/client";
import {Activity,Archive,ArrowDownToLine,ArrowUpFromLine,BarChart3,Boxes,Building2,Check,ChevronDown,ClipboardList,CreditCard,FileText,LogOut,Package,Plus,Receipt,RefreshCw,Search,Settings,ShoppingCart,Store,Truck,Users,Wallet,X} from "lucide-react";

type Merchant={id:string;store_name:string;status:string;slug:string;phone:string|null;address:string|null;description:string|null;legal_name?:string|null;rnc?:string|null};
type Product={id:string;name:string;sku:string|null;price_dop:number;cost_dop:number;stock:number;track_stock:boolean;unit:string;status:string;category_id:string|null;image_url:string|null};
type Order={id:string;order_number:number;status:string;payment_status:string;payment_method:string;customer_name:string;customer_phone:string;subtotal_dop:number;total_dop:number;source:string;delivery_mode:string;created_at:string};
type Tab="overview"|"pos"|"orders"|"products"|"inventory"|"customers"|"suppliers"|"purchases"|"expenses"|"finances"|"cash"|"locations"|"invoices"|"settings";
const tabs:{id:Tab;label:string;icon:any;group:string}[]=[
{id:"overview",label:"Resumen",icon:BarChart3,group:"GENERAL"},{id:"pos",label:"Punto de venta",icon:ShoppingCart,group:"VENTAS"},{id:"orders",label:"Pedidos",icon:Truck,group:"VENTAS"},
{id:"products",label:"Productos",icon:Package,group:"CATÁLOGO"},{id:"inventory",label:"Inventario",icon:Boxes,group:"CATÁLOGO"},
{id:"customers",label:"Clientes",icon:Users,group:"RELACIONES"},{id:"suppliers",label:"Proveedores",icon:Store,group:"RELACIONES"},
{id:"purchases",label:"Compras",icon:ArrowDownToLine,group:"CONTROL"},{id:"expenses",label:"Gastos",icon:ArrowUpFromLine,group:"CONTROL"},{id:"finances",label:"Finanzas",icon:BarChart3,group:"CONTROL"},{id:"cash",label:"Caja",icon:Wallet,group:"CONTROL"},
{id:"invoices",label:"Facturación",icon:Receipt,group:"FISCAL"},{id:"settings",label:"Configuración",icon:Settings,group:"FISCAL"}];
const money=(n:any)=>"RD$ "+Number(n||0).toLocaleString("es-DO",{minimumFractionDigits:2,maximumFractionDigits:2});
const input="w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm outline-none focus:border-[#1bb6a5] focus:ring-2 focus:ring-[#1bb6a5]/15";
const btn="inline-flex items-center justify-center gap-2 rounded-xl bg-[#172c55] px-4 py-2.5 text-xs font-extrabold text-white hover:bg-[#234477] disabled:opacity-50";
const card="rounded-2xl border border-slate-200 bg-white p-4 sm:p-5";
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="block space-y-1.5"><span className="text-[10px] font-black uppercase tracking-wider text-slate-500">{label}</span>{children}</label>}
function Notice({children,onClose}:{children:string;onClose:()=>void}){return <div role="status" className="mb-4 flex items-start gap-3 rounded-xl border border-slate-200 bg-white p-3 text-xs text-slate-700 shadow-sm"><span className="flex-1">{children}</span><button onClick={onClose}><X size={14}/></button></div>}
export default function MerchantERP(){
 const [user,setUser]=useState<any>(null),[authReady,setAuthReady]=useState(false),[authMode,setAuthMode]=useState<"login"|"register">("login");
 const [auth,setAuth]=useState({email:"",password:"",name:"",phone:""}),[merchant,setMerchant]=useState<Merchant|null>(null),[merchants,setMerchants]=useState<Merchant[]>([]);
 const [tab,setTab]=useState<Tab>("overview"),[busy,setBusy]=useState(false),[loading,setLoading]=useState(true),[notice,setNotice]=useState("");
 const [products,setProducts]=useState<Product[]>([]),[orders,setOrders]=useState<Order[]>([]),[customers,setCustomers]=useState<any[]>([]),[suppliers,setSuppliers]=useState<any[]>([]),[expenses,setExpenses]=useState<any[]>([]),[invoices,setInvoices]=useState<any[]>([]),[registers,setRegisters]=useState<any[]>([]),[sessions,setSessions]=useState<any[]>([]),[purchases,setPurchases]=useState<any[]>([]),[receivables,setReceivables]=useState<any[]>([]),[payables,setPayables]=useState<any[]>([]),[orderItems,setOrderItems]=useState<any[]>([]),[locations,setLocations]=useState<any[]>([]);
 const [search,setSearch]=useState(""),[cart,setCart]=useState<Record<string,number>>({}),[customer,setCustomer]=useState({name:"Cliente mostrador",phone:""}),[discount,setDiscount]=useState("0"),[payMethod,setPayMethod]=useState("cash");
 const [locationForm,setLocationForm]=useState({name:"",address:"",phone:""});
 const [productForm,setProductForm]=useState({name:"",sku:"",price:"",cost:"",stock:"0",unit:"unidad",track:true}),[customerForm,setCustomerForm]=useState({name:"",phone:"",email:"",tax:"",address:""}),[supplierForm,setSupplierForm]=useState({name:"",phone:"",email:"",tax:""}),[expenseForm,setExpenseForm]=useState({category:"General",description:"",amount:"",method:"cash"}),[cashForm,setCashForm]=useState({name:"Caja principal",opening:"0",counted:""}),[purchaseForm,setPurchaseForm]=useState({supplier:"",product:"",quantity:"1",cost:"",reference:""});
 const supabase=useMemo(()=>getSupabase(),[]);
 const load=useCallback(async(mid?:string)=>{
  const {data:{user:u}}=await supabase.auth.getUser();setUser(u||null);
  if(!u){setMerchants([]);setMerchant(null);setLoading(false);setAuthReady(true);return;}
  const {data:ms,error}=await supabase.from("cg_market_merchants").select("id,store_name,status,slug,phone,address,description,legal_name,rnc").eq("owner_user_id",u.id).order("created_at",{ascending:false});
  if(error)throw error;const list=(ms||[]) as Merchant[];setMerchants(list);
  const active=list.find(x=>x.id===(mid||merchant?.id))||list[0]||null;setMerchant(active);
  if(active){
   const [p,o,c,s,e,i,r,ss,po,ar,ap,loc]=await Promise.all([
    supabase.from("cg_market_products").select("id,name,sku,price_dop,cost_dop,stock,track_stock,unit,status,category_id,image_url").eq("merchant_id",active.id).order("created_at",{ascending:false}),
    supabase.from("cg_market_orders").select("id,order_number,status,payment_status,payment_method,customer_name,customer_phone,subtotal_dop,total_dop,source,delivery_mode,created_at").eq("merchant_id",active.id).order("created_at",{ascending:false}).limit(100),
    supabase.from("cg_market_customers").select("*").eq("merchant_id",active.id).order("created_at",{ascending:false}).limit(200),
    supabase.from("cg_market_suppliers").select("*").eq("merchant_id",active.id).order("created_at",{ascending:false}),
    supabase.from("cg_market_expenses").select("*").eq("merchant_id",active.id).order("expense_date",{ascending:false}).limit(100),
    supabase.from("cg_market_invoices").select("*").eq("merchant_id",active.id).order("created_at",{ascending:false}).limit(100),
    supabase.from("cg_market_cash_registers").select("*").eq("merchant_id",active.id).order("created_at"),
    supabase.from("cg_market_cash_sessions").select("*").eq("merchant_id",active.id).order("opened_at",{ascending:false}).limit(30),
    supabase.from("cg_market_purchase_orders").select("*,cg_market_suppliers(name)").eq("merchant_id",active.id).order("created_at",{ascending:false}).limit(50)
   ]);
   for(const x of [p,o,c,s,e,i,r,ss,po,ar,ap,loc])if(x.error)throw x.error;
   setProducts((p.data||[]) as Product[]);setOrders((o.data||[]) as Order[]);setCustomers(c.data||[]);setSuppliers(s.data||[]);setExpenses(e.data||[]);setInvoices(i.data||[]);setRegisters(r.data||[]);setSessions(ss.data||[]);setPurchases(po.data||[]);setReceivables(ar.data||[]);setPayables(ap.data||[]);setLocations(loc.data||[]);if((o.data||[]).length){const {data:oi,error:oe}=await supabase.from("cg_market_order_items").select("order_id,quantity,unit_cost_dop,line_total_dop").in("order_id",(o.data||[]).map((x:any)=>x.id));if(oe)throw oe;setOrderItems(oi||[]);}else setOrderItems([]);
  }else{setProducts([]);setOrders([]);setCustomers([]);setSuppliers([]);setExpenses([]);setInvoices([]);setRegisters([]);setSessions([]);setPurchases([]);}
  setLoading(false);setAuthReady(true);
 },[supabase,merchant?.id]);
 useEffect(()=>{void load().catch(e=>{setNotice(e.message||"No se pudieron cargar los datos.");setLoading(false);setAuthReady(true);});},[]);
 const refresh=async()=>{setLoading(true);try{await load(merchant?.id);}catch(e:any){setNotice(e.message||"Error al actualizar.");}finally{setLoading(false);}};
 async function authenticate(e:React.FormEvent){e.preventDefault();setBusy(true);setNotice("");try{if(authMode==="register"){const {data,error}=await supabase.auth.signUp({email:auth.email,password:auth.password,options:{data:{full_name:auth.name,phone:auth.phone}}});if(error)throw error;if(!data.session){setNotice("Cuenta creada. Confirma tu correo y luego inicia sesión.");}else{await load();}}else{const {error}=await supabase.auth.signInWithPassword({email:auth.email,password:auth.password});if(error)throw error;await load();}}catch(e:any){setNotice(e.message||"No se pudo iniciar sesión.");}finally{setBusy(false);}}
 async function applyMerchant(e:React.FormEvent){e.preventDefault();setBusy(true);try{const slug=auth.name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/(^-|-$)/g,"")+"-"+crypto.randomUUID().slice(0,5);const {error}=await supabase.from("cg_market_merchants").insert({owner_user_id:user.id,store_name:auth.name.trim(),slug,phone:auth.phone.trim(),status:"pending"});if(error)throw error;setNotice("Solicitud enviada. El equipo administrador debe aprobar tu comercio.");await load();}catch(e:any){setNotice(e.message||"No se pudo enviar la solicitud.");}finally{setBusy(false);}}
 async function saveProduct(e:React.FormEvent){e.preventDefault();if(!merchant)return;setBusy(true);try{const {error}=await supabase.from("cg_market_products").insert({merchant_id:merchant.id,name:productForm.name.trim(),sku:productForm.sku.trim()||null,price_dop:Number(productForm.price),cost_dop:Number(productForm.cost||0),stock:Number(productForm.stock),track_stock:productForm.track,unit:productForm.unit,status:"active"});if(error)throw error;setProductForm({name:"",sku:"",price:"",cost:"",stock:"0",unit:"unidad",track:true});setNotice("Producto guardado en tu catálogo.");await refresh();}catch(e:any){setNotice(e.message||"No se pudo guardar el producto.");}finally{setBusy(false);}}
 async function adjustStock(p:Product,delta:number){const qty=window.prompt("Cantidad a "+(delta>0?"sumar":"retirar")+" para "+p.name+":");if(qty===null)return;const n=Number(qty);if(!Number.isInteger(n)||n<1){setNotice("Escribe una cantidad entera mayor que cero.");return;}setBusy(true);try{const {error}=await supabase.rpc("cg_market_adjust_stock",{p_product_id:p.id,p_delta:delta*n,p_note:"Ajuste desde el panel del comercio"});if(error)throw error;setNotice("Inventario actualizado.");await refresh();}catch(e:any){setNotice(e.message||"No se pudo ajustar el inventario.");}finally{setBusy(false);}}
 const cartLines=products.filter(p=>cart[p.id]>0);const subtotal=cartLines.reduce((n,p)=>n+Number(p.price_dop)*cart[p.id],0);const total=Math.max(0,subtotal-Number(discount||0));
 async function checkout(){if(!merchant||!cartLines.length)return;setBusy(true);try{const items=cartLines.map(p=>({product_id:p.id,quantity:cart[p.id]}));const {data,error}=await supabase.rpc("cg_market_create_order",{p_merchant_id:merchant.id,p_items:items,p_customer_name:customer.name||"Cliente mostrador",p_customer_phone:customer.phone||merchant.phone||"",p_delivery_mode:"pickup",p_address:null,p_lat:null,p_lng:null,p_payment_method:payMethod,p_notes:"Venta registrada en POS",p_source:"pos",p_discount_dop:Number(discount||0)});if(error)throw error;
 const orderId=data.order_id;const open=sessions.find(x=>x.status==="open");if(open&&payMethod==="cash"){const {error:cashError}=await supabase.rpc("cg_market_add_cash_movement",{p_session_id:open.id,p_type:"sale",p_description:"Venta POS #"+data.order_number,p_amount:data.total_dop,p_reference_id:orderId});if(cashError)setNotice("Venta registrada, pero no se pudo reflejar en el turno de caja: "+cashError.message);}
 setCart({});setDiscount("0");setNotice("Venta #"+data.order_number+" registrada. Total: "+money(data.total_dop));await refresh();
 }catch(e:any){setNotice(e.message||"No se pudo completar la venta.");}finally{setBusy(false);}}
 async function updateOrder(id:string,status:string,payment?:string){setBusy(true);try{const {error}=await supabase.rpc("cg_market_update_order",{p_order_id:id,p_status:status||null,p_payment_status:payment||null});if(error)throw error;setNotice("Pedido actualizado.");await refresh();}catch(e:any){setNotice(e.message||"No se pudo actualizar el pedido.");}finally{setBusy(false);}}
 async function saveCustomer(e:React.FormEvent){e.preventDefault();setBusy(true);try{const {error}=await supabase.from("cg_market_customers").insert({merchant_id:merchant?.id,full_name:customerForm.name,phone:customerForm.phone,email:customerForm.email||null,tax_id:customerForm.tax||null,address:customerForm.address||null});if(error)throw error;setCustomerForm({name:"",phone:"",email:"",tax:"",address:""});setNotice("Cliente guardado.");await refresh();}catch(e:any){setNotice(e.message||"Error guardando cliente.");}finally{setBusy(false);}}
 async function saveSupplier(e:React.FormEvent){e.preventDefault();setBusy(true);try{const {error}=await supabase.from("cg_market_suppliers").insert({merchant_id:merchant?.id,name:supplierForm.name,phone:supplierForm.phone,email:supplierForm.email||null,tax_id:supplierForm.tax||null});if(error)throw error;setSupplierForm({name:"",phone:"",email:"",tax:""});setNotice("Proveedor guardado.");await refresh();}catch(e:any){setNotice(e.message||"Error guardando proveedor.");}finally{setBusy(false);}}
 async function saveExpense(e:React.FormEvent){e.preventDefault();setBusy(true);try{const {error}=await supabase.from("cg_market_expenses").insert({merchant_id:merchant?.id,category:expenseForm.category,description:expenseForm.description,amount_dop:Number(expenseForm.amount),payment_method:expenseForm.method,created_by:user.id});if(error)throw error;const open=sessions.find(x=>x.status==="open");if(open&&expenseForm.method==="cash"){const {error:cashError}=await supabase.rpc("cg_market_add_cash_movement",{p_session_id:open.id,p_type:"expense",p_description:expenseForm.description,p_amount:Number(expenseForm.amount),p_reference_id:null});if(cashError)setNotice("Gasto registrado, pero no se reflejó en caja: "+cashError.message);}setExpenseForm({category:"General",description:"",amount:"",method:"cash"});setNotice("Gasto registrado.");await refresh();}catch(e:any){setNotice(e.message||"Error guardando gasto.");}finally{setBusy(false);}}
 async function createPurchase(e:React.FormEvent){e.preventDefault();setBusy(true);try{const prod=products.find(x=>x.id===purchaseForm.product);if(!prod)throw new Error("Selecciona un producto válido.");const {data:po,error}=await supabase.from("cg_market_purchase_orders").insert({merchant_id:merchant?.id,supplier_id:purchaseForm.supplier||null,reference:purchaseForm.reference||null,created_by:user.id}).select("id").single();if(error)throw error;const {error:itemError}=await supabase.from("cg_market_purchase_items").insert({purchase_id:po.id,product_id:prod.id,quantity:Number(purchaseForm.quantity),unit_cost_dop:Number(purchaseForm.cost)});if(itemError)throw itemError;const {error:receiveError}=await supabase.rpc("cg_market_receive_purchase",{p_purchase_id:po.id});if(receiveError)throw receiveError;setPurchaseForm({supplier:"",product:"",quantity:"1",cost:"",reference:""});setNotice("Compra recibida e inventario actualizado.");await refresh();}catch(e:any){setNotice(e.message||"No se pudo registrar la compra.");}finally{setBusy(false);}}
 async function newReceivable(){if(!merchant)return;const name=window.prompt("Nombre del cliente");if(!name?.trim())return;const desc=window.prompt("Concepto de la cuenta","Venta pendiente");if(desc===null)return;const amount=Number(window.prompt("Monto pendiente en RD$",""));if(!Number.isFinite(amount)||amount<=0){setNotice("Monto no válido.");return;}const due=window.prompt("Fecha de vencimiento YYYY-MM-DD (opcional)","");const {error}=await supabase.from("cg_market_receivables").insert({merchant_id:merchant.id,customer_name:name.trim(),description:desc,amount_dop:amount,due_date:due||null,created_by:user.id});setNotice(error?error.message:"Cuenta por cobrar creada.");await refresh();}
 async function payReceivable(r:any){const amount=Number(window.prompt("Monto recibido (saldo "+money(Number(r.amount_dop)-Number(r.paid_dop))+")",""));if(!Number.isFinite(amount)||amount<=0)return;const method=window.prompt("Método: cash, transfer, card u other","cash")||"cash";setBusy(true);try{const {error}=await supabase.rpc("cg_market_record_receivable_payment",{p_receivable_id:r.id,p_amount:amount,p_method:method,p_reference:null});if(error)throw error;setNotice("Abono registrado.");await refresh();}catch(e:any){setNotice(e.message||"No se pudo registrar el abono.");}finally{setBusy(false);}}
 async function newPayable(){if(!merchant)return;const desc=window.prompt("Concepto de la cuenta por pagar");if(!desc?.trim())return;const amount=Number(window.prompt("Monto a pagar en RD$",""));if(!Number.isFinite(amount)||amount<=0){setNotice("Monto no válido.");return;}const choice=suppliers.length?window.prompt("Selecciona proveedor por número (opcional): "+suppliers.map((s,i)=>(i+1)+". "+s.name).join(" · "),""):"";const supplier=choice&&Number.isInteger(Number(choice))?suppliers[Number(choice)-1]?.id||null:null;const due=window.prompt("Fecha de vencimiento YYYY-MM-DD (opcional)","");const {error}=await supabase.from("cg_market_payables").insert({merchant_id:merchant.id,supplier_id:supplier,description:desc.trim(),amount_dop:amount,due_date:due||null,created_by:user.id});setNotice(error?error.message:"Cuenta por pagar creada.");await refresh();}
 async function payPayable(r:any){const amount=Number(window.prompt("Monto pagado (saldo "+money(Number(r.amount_dop)-Number(r.paid_dop))+")",""));if(!Number.isFinite(amount)||amount<=0)return;const method=window.prompt("Método: cash, transfer, card u other","cash")||"cash";setBusy(true);try{const {error}=await supabase.rpc("cg_market_record_payable_payment",{p_payable_id:r.id,p_amount:amount,p_method:method,p_reference:null});if(error)throw error;setNotice("Pago registrado.");await refresh();}catch(e:any){setNotice(e.message||"No se pudo registrar el pago.");}finally{setBusy(false);}}
 async function saveLocation(e:React.FormEvent){e.preventDefault();setBusy(true);try{const {error}=await supabase.from("cg_market_locations").insert({merchant_id:merchant?.id,name:locationForm.name.trim(),address:locationForm.address||null,phone:locationForm.phone||null,is_default:locations.length===0});if(error)throw error;setLocationForm({name:"",address:"",phone:""});setNotice("Sucursal guardada.");await refresh();}catch(e:any){setNotice(e.message||"No se pudo guardar la sucursal.");}finally{setBusy(false);}}
 async function createRegister(e:React.FormEvent){e.preventDefault();setBusy(true);try{const {error}=await supabase.from("cg_market_cash_registers").insert({merchant_id:merchant?.id,name:cashForm.name});if(error)throw error;setNotice("Caja creada.");await refresh();}catch(e:any){setNotice(e.message||"No se pudo crear la caja.");}finally{setBusy(false);}}
 async function openCash(id:string){setBusy(true);try{const {error}=await supabase.rpc("cg_market_open_cash_session",{p_register_id:id,p_opening_cash:Number(cashForm.opening||0)});if(error)throw error;setNotice("Turno de caja abierto.");await refresh();}catch(e:any){setNotice(e.message||"No se pudo abrir caja.");}finally{setBusy(false);}}
 async function closeCash(id:string){const amount=window.prompt("¿Cuánto efectivo contaste al cerrar la caja?");if(amount===null)return;setBusy(true);try{const {data,error}=await supabase.rpc("cg_market_close_cash_session",{p_session_id:id,p_counted_cash:Number(amount)});if(error)throw error;setNotice("Caja cerrada. Diferencia: "+money(data.difference_dop));await refresh();}catch(e:any){setNotice(e.message||"No se pudo cerrar caja.");}finally{setBusy(false);}}
 const filtered=products.filter(p=>(p.name+" "+(p.sku||"")).toLowerCase().includes(search.toLowerCase()));
 const today=new Date().toLocaleDateString("en-CA");const todayOrders=orders.filter(o=>o.created_at.slice(0,10)===today);const sales=todayOrders.filter(o=>o.payment_status==="paid").reduce((n,o)=>n+Number(o.total_dop),0);const expenseToday=expenses.filter(e=>e.expense_date===today).reduce((n,e)=>n+Number(e.amount_dop),0);
 const paidIds=new Set(todayOrders.filter(o=>o.payment_status==="paid").map(o=>o.id));const costOfSales=orderItems.filter(x=>paidIds.has(x.order_id)).reduce((n,x)=>n+Number(x.unit_cost_dop||0)*Number(x.quantity||0),0);const grossProfit=sales-costOfSales;const netProfit=grossProfit-expenseToday;const openSession=sessions.find(s=>s.status==="open");
 const [mobileNav,setMobileNav]=useState(false);
 if(!authReady||loading)return <main className="grid min-h-screen place-items-center bg-[#f5f7fb] text-sm font-bold text-slate-500"><RefreshCw className="mr-2 inline animate-spin"/> Cargando tu negocio…</main>;
 if(!user)return <main className="grid min-h-screen place-items-center bg-[#f5f7fb] p-4"><form onSubmit={authenticate} className="w-full max-w-md rounded-3xl border border-slate-200 bg-white p-7 shadow-xl"><div className="mb-5 flex items-center gap-3"><div className="grid h-11 w-11 place-items-center rounded-xl bg-[#172c55] text-white"><Building2/></div><div><div className="text-xl font-black text-[#172c55]">Portal de negocios</div><div className="text-xs text-slate-400">Acceso seguro a tu comercio</div></div></div><h1 className="text-2xl font-black">{authMode==="login"?"Bienvenido de nuevo":"Crear cuenta de negocio"}</h1><p className="mb-5 mt-1 text-xs text-slate-500">Administra ventas, inventario, caja y pedidos desde un solo lugar.</p>{authMode==="register"&&<><Field label="Nombre completo"><input required className={input} value={auth.name} onChange={e=>setAuth({...auth,name:e.target.value})}/></Field><div className="h-3"/><Field label="Teléfono"><input className={input} value={auth.phone} onChange={e=>setAuth({...auth,phone:e.target.value})}/></Field><div className="h-3"/></>}<Field label="Correo"><input type="email" required className={input} value={auth.email} onChange={e=>setAuth({...auth,email:e.target.value})}/></Field><div className="h-3"/><Field label="Contraseña"><input type="password" required minLength={8} className={input} value={auth.password} onChange={e=>setAuth({...auth,password:e.target.value})}/></Field>{notice&&<p className="my-3 rounded-lg bg-amber-50 p-3 text-xs">{notice}</p>}<button className={btn+" mt-5 w-full"} disabled={busy}>{busy?"Procesando…":authMode==="login"?"Iniciar sesión":"Crear cuenta"}</button><button type="button" className="mt-4 w-full text-xs font-bold text-slate-500 underline" onClick={()=>setAuthMode(authMode==="login"?"register":"login")}>{authMode==="login"?"No tengo cuenta · Registrarme":"Ya tengo cuenta · Iniciar sesión"}</button></form></main>;
 if(!merchant)return <main className="grid min-h-screen place-items-center bg-[#f5f7fb] p-4"><div className="w-full max-w-xl rounded-3xl border bg-white p-7"><div className="text-xs font-black uppercase tracking-widest text-[#168f83]">Portal de comercios</div><h1 className="mt-2 text-3xl font-black">Registra tu negocio</h1><p className="mt-2 text-sm text-slate-500">Solicita acceso al catálogo, punto de venta, inventario y facturación.</p>{notice&&<p className="my-4 rounded-xl bg-amber-50 p-3 text-xs">{notice}</p>}{merchants.length>0&&<div className="my-4 space-y-2">{merchants.map(m=><div key={m.id} className="rounded-xl bg-slate-50 p-3 text-sm"><b>{m.store_name}</b><span className="ml-2 text-xs text-slate-500">Estado: {m.status==="pending"?"Pendiente":m.status}</span></div>)}</div>}<form onSubmit={applyMerchant} className="mt-5 space-y-3"><Field label="Nombre del comercio"><input required className={input} value={auth.name} onChange={e=>setAuth({...auth,name:e.target.value})}/></Field><Field label="Teléfono"><input required className={input} value={auth.phone} onChange={e=>setAuth({...auth,phone:e.target.value})}/></Field><button className={btn+" w-full"} disabled={busy}>Enviar solicitud de registro</button></form><button onClick={()=>supabase.auth.signOut().then(()=>load())} className="mt-4 text-xs underline">Cerrar sesión</button></div></main>;
 if(merchant.status!=="approved")return <main className="grid min-h-screen place-items-center bg-[#f5f7fb] p-4"><div className="w-full max-w-lg rounded-3xl border bg-white p-7"><div className="text-xs font-black uppercase tracking-widest text-amber-600">Solicitud en revisión</div><h1 className="mt-2 text-3xl font-black">{merchant.store_name}</h1><p className="mt-3 text-sm leading-6 text-slate-500">Tu solicitud todavía no está aprobada. Cuando administración la apruebe, tendrás acceso a tu POS, inventario, pedidos y reportes.</p><button onClick={refresh} className={btn+" mt-5"}><RefreshCw size={14}/> Actualizar estado</button><button onClick={()=>supabase.auth.signOut().then(()=>load())} className="ml-3 text-xs underline">Salir</button></div></main>;
 const groups=Array.from(new Set(tabs.map(t=>t.group)));
 return <div className="min-h-screen bg-[#f5f7fb] text-[#172033]"><div className="flex min-h-screen">
 <aside className={(mobileNav?"fixed inset-y-0 left-0 z-50 flex":"hidden")+" w-[250px] shrink-0 flex-col border-r border-slate-200 bg-white lg:sticky lg:top-0 lg:flex lg:h-screen"}><div className="flex h-[76px] items-center gap-3 border-b px-5"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#172c55] text-white"><Activity/></div><div><b className="text-xl tracking-tight text-[#172c55]">Comercios<span className="text-[#1bb6a5]">.</span></b><div className="text-[9px] font-bold uppercase tracking-widest text-slate-400">Panel de gestión</div></div></div><div className="p-4"><select value={merchant.id} onChange={e=>load(e.target.value)} className={input}>{merchants.map(m=><option key={m.id} value={m.id}>{m.store_name}</option>)}</select></div><nav className="flex-1 space-y-5 overflow-y-auto px-3 pb-5">{groups.map(g=><div key={g}><p className="px-3 pb-2 text-[9px] font-black tracking-widest text-slate-400">{g}</p>{tabs.filter(t=>t.group===g).map(t=><button key={t.id} onClick={()=>{setTab(t.id);setMobileNav(false);setNotice("");}} className={"flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-xs font-bold "+(tab===t.id?"bg-[#edf3fb] text-[#1b3b70]":"text-slate-500 hover:bg-slate-50")}><t.icon size={16}/>{t.label}</button>)}</div>)}</nav><div className="border-t p-4"><button onClick={()=>supabase.auth.signOut().then(()=>load())} className="flex w-full items-center gap-2 text-xs font-bold text-slate-500"><LogOut size={15}/> Cerrar sesión</button></div></aside>
 {mobileNav&&<button onClick={()=>setMobileNav(false)} className="fixed inset-0 z-40 bg-black/30 lg:hidden"/>}
 <section className="min-w-0 flex-1"><header className="sticky top-0 z-30 flex h-[76px] items-center justify-between border-b bg-white/95 px-4 backdrop-blur sm:px-7"><div className="flex items-center gap-3"><button onClick={()=>setMobileNav(true)} className="rounded-lg p-2 lg:hidden">☰</button><div><div className="text-[10px] text-slate-400">{merchant.store_name} / Panel de negocio</div><h1 className="text-lg font-black">{tabs.find(t=>t.id===tab)?.label}</h1></div></div><div className="flex items-center gap-3"><span className="hidden rounded-full bg-emerald-50 px-3 py-2 text-[10px] font-bold text-emerald-700 sm:block">Comercio aprobado</span><button onClick={refresh} className="rounded-lg border p-2 text-slate-500"><RefreshCw size={16}/></button></div></header>
 <main className="mx-auto max-w-[1440px] p-4 sm:p-7">{notice&&<Notice onClose={()=>setNotice("")}>{notice}</Notice>}
 {tab==="overview"&&<><div className="mb-6"><p className="text-xs text-slate-400">Resumen de tu operación</p><h2 className="mt-1 text-2xl font-black">Hola, {merchant.store_name}</h2><p className="mt-1 text-xs text-slate-500">Aquí tienes lo más importante de tu negocio.</p></div><div className="grid grid-cols-2 gap-3 xl:grid-cols-4">{[{label:"Ventas cobradas hoy",value:money(sales),icon:CreditCard},{label:"Pedidos hoy",value:String(todayOrders.length),icon:Truck},{label:"Productos",value:String(products.length),icon:Package},{label:"Gastos registrados",value:money(expenseToday),icon:ArrowUpFromLine}].map(x=><div key={x.label} className={card}><div className="flex items-center justify-between text-xs font-bold text-slate-500">{x.label}<x.icon size={17} className="text-[#168f83]"/></div><div className="mt-3 text-2xl font-black">{x.value}</div></div>)}</div><div className="mt-5 grid gap-5 xl:grid-cols-2"><div className={card}><h3 className="font-black">Últimas ventas y pedidos</h3>{orders.slice(0,6).map(o=><div key={o.id} className="flex items-center justify-between border-b py-3 last:border-0"><div><b className="text-xs">Pedido #{o.order_number}</b><p className="text-[10px] text-slate-400">{o.customer_name} · {new Date(o.created_at).toLocaleString("es-DO")}</p></div><div className="text-right"><b className="text-xs">{money(o.total_dop)}</b><p className="text-[10px] text-slate-400">{o.status}</p></div></div>)}{!orders.length&&<p className="py-8 text-center text-xs text-slate-400">Todavía no hay ventas.</p>}</div><div className={card}><h3 className="font-black">Inventario para revisar</h3>{products.filter(p=>p.track_stock&&p.stock<6).slice(0,8).map(p=><div key={p.id} className="flex items-center justify-between border-b py-3 last:border-0"><span className="text-xs font-bold">{p.name}</span><span className="rounded-full bg-amber-50 px-3 py-1 text-[10px] font-black text-amber-700">{p.stock} disponibles</span></div>)}{!products.some(p=>p.track_stock&&p.stock<6)&&<p className="py-8 text-center text-xs text-slate-400">No hay productos con stock crítico.</p>}</div></div></>}
 {tab==="products"&&<div className="grid gap-5 xl:grid-cols-[1fr_350px]"><section className={card}><div className="flex items-center justify-between gap-2"><h2 className="font-black">Catálogo de productos</h2><span className="text-xs text-slate-400">{products.length} productos</span></div><input className={input+" mt-4"} placeholder="Buscar por nombre o SKU…" value={search} onChange={e=>setSearch(e.target.value)}/><div className="mt-3 divide-y">{filtered.map(p=><div key={p.id} className="flex items-center justify-between gap-3 py-3"><div className="min-w-0"><b className="block truncate text-xs">{p.name}</b><span className="text-[10px] text-slate-400">{p.sku||"Sin SKU"} · Costo {money(p.cost_dop)}</span></div><div className="text-right"><b className="text-xs">{money(p.price_dop)}</b><p className="text-[10px] text-slate-400">Stock {p.track_stock?p.stock:"No controlado"}</p></div></div>)}</div></section><form onSubmit={saveProduct} className={card+" h-fit space-y-3"}><h3 className="font-black">Agregar producto</h3><Field label="Nombre"><input required className={input} value={productForm.name} onChange={e=>setProductForm({...productForm,name:e.target.value})}/></Field><Field label="Código SKU"><input className={input} value={productForm.sku} onChange={e=>setProductForm({...productForm,sku:e.target.value})}/></Field><div className="grid grid-cols-2 gap-2"><Field label="Precio venta RD$"><input required type="number" min="0" step=".01" className={input} value={productForm.price} onChange={e=>setProductForm({...productForm,price:e.target.value})}/></Field><Field label="Costo RD$"><input type="number" min="0" step=".01" className={input} value={productForm.cost} onChange={e=>setProductForm({...productForm,cost:e.target.value})}/></Field></div><div className="grid grid-cols-2 gap-2"><Field label="Existencia inicial"><input type="number" min="0" className={input} value={productForm.stock} onChange={e=>setProductForm({...productForm,stock:e.target.value})}/></Field><Field label="Unidad"><select className={input} value={productForm.unit} onChange={e=>setProductForm({...productForm,unit:e.target.value})}><option>unidad</option><option>caja</option><option>libra</option><option>paquete</option><option>servicio</option></select></Field></div><label className="flex items-center gap-2 text-xs"><input type="checkbox" checked={productForm.track} onChange={e=>setProductForm({...productForm,track:e.target.checked})}/> Controlar inventario</label><button disabled={busy} className={btn+" w-full"}><Plus size={14}/> Guardar producto</button></form></div>}
 {tab==="inventory"&&<section className={card}><h2 className="font-black">Control de inventario</h2><p className="mt-1 text-xs text-slate-500">Cada ajuste queda registrado en el historial de movimientos.</p><div className="mt-4 overflow-x-auto"><table className="w-full text-left text-xs"><thead className="bg-slate-50 text-[10px] text-slate-400"><tr><th className="p-3">Producto</th><th className="p-3">SKU</th><th className="p-3">Existencia</th><th className="p-3">Acciones</th></tr></thead><tbody>{products.map(p=><tr key={p.id} className="border-t"><td className="p-3 font-bold">{p.name}</td><td className="p-3">{p.sku||"—"}</td><td className="p-3">{p.track_stock?p.stock:"No controla"}</td><td className="p-3"><div className="flex gap-2"><button disabled={busy||!p.track_stock} onClick={()=>adjustStock(p,1)} className="rounded-lg border px-3 py-1.5">+ Stock</button><button disabled={busy||!p.track_stock||p.stock===0} onClick={()=>adjustStock(p,-1)} className="rounded-lg border px-3 py-1.5">− Stock</button></div></td></tr>)}</tbody></table></div></section>}
 {tab==="pos"&&<div className="grid gap-5 xl:grid-cols-[1fr_340px]"><section className={card}><h2 className="font-black">Punto de venta</h2><div className="relative mt-3"><Search size={15} className="absolute left-3 top-3 text-slate-400"/><input className={input+" pl-9"} placeholder="Buscar producto…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">{filtered.filter(p=>p.status==="active").map(p=><button key={p.id} onClick={()=>setCart(c=>({...c,[p.id]:(c[p.id]||0)+1}))} disabled={p.track_stock&&p.stock<=0} className="rounded-xl border p-3 text-left hover:border-[#1bb6a5] disabled:opacity-40"><div className="grid h-16 place-items-center rounded-lg bg-slate-50 text-slate-300"><Package size={24}/></div><b className="mt-2 block text-xs">{p.name}</b><span className="text-[10px] text-slate-400">Stock {p.track_stock?p.stock:"∞"}</span><strong className="mt-2 block text-sm">{money(p.price_dop)}</strong></button>)}</div></section><section className={card+" h-fit"}><h3 className="font-black">Carrito de venta</h3>{cartLines.map(p=><div key={p.id} className="flex items-center justify-between gap-2 border-b py-3"><div className="min-w-0"><b className="block truncate text-xs">{p.name}</b><span className="text-[10px] text-slate-400">{money(p.price_dop)} c/u</span></div><div className="flex items-center gap-2"><button onClick={()=>setCart(c=>({...c,[p.id]:Math.max(0,c[p.id]-1)}))}>−</button><b className="text-xs">{cart[p.id]}</b><button onClick={()=>setCart(c=>({...c,[p.id]:c[p.id]+1}))} disabled={p.track_stock&&cart[p.id]>=p.stock}>+</button></div></div>)}{!cartLines.length&&<p className="py-8 text-center text-xs text-slate-400">Agrega productos para comenzar.</p>}<div className="mt-4 space-y-3"><Field label="Cliente"><input className={input} value={customer.name} onChange={e=>setCustomer({...customer,name:e.target.value})}/></Field><Field label="Teléfono"><input className={input} value={customer.phone} onChange={e=>setCustomer({...customer,phone:e.target.value})}/></Field><Field label="Descuento RD$"><input className={input} type="number" min="0" max={subtotal} value={discount} onChange={e=>setDiscount(e.target.value)}/></Field><Field label="Forma de pago"><select className={input} value={payMethod} onChange={e=>setPayMethod(e.target.value)}><option value="cash">Efectivo</option><option value="transfer">Transferencia</option></select></Field><div className="flex justify-between border-t pt-3 text-sm"><b>Total</b><b>{money(total)}</b></div><button disabled={busy||!cartLines.length} onClick={checkout} className={btn+" w-full"}><CreditCard size={15}/> Cobrar y registrar venta</button><p className="text-[9px] leading-4 text-slate-400">La venta se registra como cobrada en el sistema y descuenta inventario automáticamente.</p></div></section></div>}
 {tab==="orders"&&<section className={card}><h2 className="font-black">Pedidos recibidos</h2><div className="mt-4 space-y-3">{orders.map(o=><div key={o.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border p-3"><div><b className="text-xs">Pedido #{o.order_number} · {o.customer_name}</b><p className="mt-1 text-[10px] text-slate-400">{o.customer_phone} · {o.source} · {new Date(o.created_at).toLocaleString("es-DO")}</p><p className="mt-1 text-xs font-bold">{money(o.total_dop)} · {o.payment_status==="paid"?"Pagado":"Pendiente de pago"}</p></div><div className="flex flex-wrap gap-2"><select value={o.status} onChange={e=>updateOrder(o.id,e.target.value)} className="rounded-lg border px-2 py-2 text-[10px]"><option value={o.status}>{o.status}</option><option value="accepted">Aceptar</option><option value="preparing">Preparando</option><option value="ready_for_pickup">Listo</option><option value="completed">Completado (recogida)</option><option value="rejected">Rechazar</option></select>{o.payment_status!=="paid"&&<button onClick={()=>updateOrder(o.id,"","paid")} className="rounded-lg border px-3 py-2 text-[10px] font-bold">Marcar pagado</button>}</div></div>)}{!orders.length&&<p className="py-8 text-center text-xs text-slate-400">No hay pedidos todavía.</p>}</div></section>}
 {tab==="customers"&&<div className="grid gap-5 xl:grid-cols-[1fr_350px]"><section className={card}><h2 className="font-black">Clientes</h2>{customers.map(c=><div key={c.id} className="flex justify-between border-b py-3 text-xs"><div><b>{c.full_name}</b><p className="text-[10px] text-slate-400">{c.phone} · {c.email||""}</p></div><span className="text-slate-400">{c.tax_id||""}</span></div>)}</section><form onSubmit={saveCustomer} className={card+" h-fit space-y-3"}><h3 className="font-black">Agregar cliente</h3><Field label="Nombre"><input required className={input} value={customerForm.name} onChange={e=>setCustomerForm({...customerForm,name:e.target.value})}/></Field><Field label="Teléfono"><input className={input} value={customerForm.phone} onChange={e=>setCustomerForm({...customerForm,phone:e.target.value})}/></Field><Field label="Correo"><input type="email" className={input} value={customerForm.email} onChange={e=>setCustomerForm({...customerForm,email:e.target.value})}/></Field><Field label="RNC / Cédula"><input className={input} value={customerForm.tax} onChange={e=>setCustomerForm({...customerForm,tax:e.target.value})}/></Field><Field label="Dirección"><input className={input} value={customerForm.address} onChange={e=>setCustomerForm({...customerForm,address:e.target.value})}/></Field><button className={btn+" w-full"}>Guardar cliente</button></form></div>}
 {tab==="suppliers"&&<div className="grid gap-5 xl:grid-cols-[1fr_350px]"><section className={card}><h2 className="font-black">Proveedores</h2>{suppliers.map(s=><div key={s.id} className="border-b py-3 text-xs"><b>{s.name}</b><p className="text-[10px] text-slate-400">{s.phone} · {s.email||""}</p></div>)}</section><form onSubmit={saveSupplier} className={card+" h-fit space-y-3"}><h3 className="font-black">Nuevo proveedor</h3><Field label="Nombre"><input required className={input} value={supplierForm.name} onChange={e=>setSupplierForm({...supplierForm,name:e.target.value})}/></Field><Field label="Teléfono"><input className={input} value={supplierForm.phone} onChange={e=>setSupplierForm({...supplierForm,phone:e.target.value})}/></Field><Field label="Correo"><input className={input} value={supplierForm.email} onChange={e=>setSupplierForm({...supplierForm,email:e.target.value})}/></Field><Field label="RNC"><input className={input} value={supplierForm.tax} onChange={e=>setSupplierForm({...supplierForm,tax:e.target.value})}/></Field><button className={btn+" w-full"}>Guardar proveedor</button></form></div>}
 {tab==="purchases"&&<div className="grid gap-5 xl:grid-cols-[1fr_360px]"><section className={card}><h2 className="font-black">Compras y recepción</h2>{purchases.map(p=><div key={p.id} className="flex justify-between border-b py-3 text-xs"><div><b>{p.reference||"Compra"}</b><p className="text-[10px] text-slate-400">{p.cg_market_suppliers?.name||"Sin proveedor"} · {p.status}</p></div><b>{money(p.subtotal_dop)}</b></div>)}</section><form onSubmit={createPurchase} className={card+" h-fit space-y-3"}><h3 className="font-black">Registrar compra y recibir</h3><Field label="Proveedor"><select className={input} value={purchaseForm.supplier} onChange={e=>setPurchaseForm({...purchaseForm,supplier:e.target.value})}><option value="">Sin proveedor</option>{suppliers.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></Field><Field label="Producto"><select required className={input} value={purchaseForm.product} onChange={e=>setPurchaseForm({...purchaseForm,product:e.target.value})}><option value="">Selecciona producto</option>{products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><div className="grid grid-cols-2 gap-2"><Field label="Cantidad"><input required type="number" min="1" className={input} value={purchaseForm.quantity} onChange={e=>setPurchaseForm({...purchaseForm,quantity:e.target.value})}/></Field><Field label="Costo unitario"><input required type="number" min="0" step=".01" className={input} value={purchaseForm.cost} onChange={e=>setPurchaseForm({...purchaseForm,cost:e.target.value})}/></Field></div><Field label="Referencia"><input className={input} value={purchaseForm.reference} onChange={e=>setPurchaseForm({...purchaseForm,reference:e.target.value})}/></Field><button className={btn+" w-full"}>Recibir compra e incrementar stock</button></form></div>}
 {tab==="expenses"&&<div className="grid gap-5 xl:grid-cols-[1fr_350px]"><section className={card}><h2 className="font-black">Gastos del negocio</h2>{expenses.map(e=><div key={e.id} className="flex justify-between border-b py-3 text-xs"><div><b>{e.description}</b><p className="text-[10px] text-slate-400">{e.category} · {e.expense_date}</p></div><b>{money(e.amount_dop)}</b></div>)}</section><form onSubmit={saveExpense} className={card+" h-fit space-y-3"}><h3 className="font-black">Registrar gasto</h3><Field label="Categoría"><select className={input} value={expenseForm.category} onChange={e=>setExpenseForm({...expenseForm,category:e.target.value})}><option>General</option><option>Alquiler</option><option>Servicios</option><option>Transporte</option><option>Nómina</option><option>Marketing</option><option>Otros</option></select></Field><Field label="Descripción"><input required className={input} value={expenseForm.description} onChange={e=>setExpenseForm({...expenseForm,description:e.target.value})}/></Field><Field label="Monto RD$"><input required type="number" min=".01" step=".01" className={input} value={expenseForm.amount} onChange={e=>setExpenseForm({...expenseForm,amount:e.target.value})}/></Field><Field label="Método de pago"><select className={input} value={expenseForm.method} onChange={e=>setExpenseForm({...expenseForm,method:e.target.value})}><option value="cash">Efectivo</option><option value="transfer">Transferencia</option><option value="card">Tarjeta</option><option value="other">Otro</option></select></Field><button className={btn+" w-full"}>Guardar gasto</button></form></div>}
 {tab==="finances"&&<div className="space-y-5"><div className="grid grid-cols-2 gap-3 lg:grid-cols-4">{[{l:"Ventas cobradas",v:money(sales)},{l:"Costo de ventas estimado",v:money(costOfSales)},{l:"Ganancia bruta estimada",v:money(grossProfit)},{l:"Resultado después de gastos",v:money(netProfit)}].map(x=><div key={x.l} className={card}><div className="text-[10px] font-bold text-slate-500">{x.l}</div><div className="mt-2 text-xl font-black">{x.v}</div></div>)}</div><div className="grid gap-5 xl:grid-cols-2"><section className={card}><div className="flex items-center justify-between"><h3 className="font-black">Cuentas por cobrar</h3><button onClick={newReceivable} className={btn}><Plus size={13}/> Agregar</button></div>{receivables.map(r=><div key={r.id} className="flex flex-wrap items-center justify-between gap-2 border-b py-3 text-xs"><div><b>{r.customer_name}</b><p className="text-[10px] text-slate-400">{r.description||"Cuenta"} · {r.status} · vence {r.due_date||"sin fecha"}</p><span className="text-[10px] text-slate-500">Saldo: {money(Number(r.amount_dop)-Number(r.paid_dop))}</span></div>{r.status!=="paid"&&r.status!=="cancelled"&&<button onClick={()=>payReceivable(r)} className="rounded-lg border px-3 py-2 text-[10px] font-bold">Registrar abono</button>}</div>)}{!receivables.length&&<p className="py-5 text-xs text-slate-400">No tienes cuentas por cobrar.</p>}</section><section className={card}><div className="flex items-center justify-between"><h3 className="font-black">Cuentas por pagar</h3><button onClick={newPayable} className={btn}><Plus size={13}/> Agregar</button></div>{payables.map(r=><div key={r.id} className="flex flex-wrap items-center justify-between gap-2 border-b py-3 text-xs"><div><b>{r.description}</b><p className="text-[10px] text-slate-400">{r.status} · vence {r.due_date||"sin fecha"}</p><span className="text-[10px] text-slate-500">Saldo: {money(Number(r.amount_dop)-Number(r.paid_dop))}</span></div>{r.status!=="paid"&&r.status!=="cancelled"&&<button onClick={()=>payPayable(r)} className="rounded-lg border px-3 py-2 text-[10px] font-bold">Registrar pago</button>}</div>)}{!payables.length&&<p className="py-5 text-xs text-slate-400">No tienes cuentas por pagar.</p>}</section></div><p className="text-[10px] leading-4 text-slate-400">La ganancia es una estimación gerencial calculada con el costo guardado al registrar cada venta; no sustituye estados financieros ni declaraciones fiscales.</p></div>}
 {tab==="cash"&&<div className="grid gap-5 xl:grid-cols-[1fr_350px]"><section className={card}><h2 className="font-black">Cajas y turnos</h2>{registers.map(r=><div key={r.id} className="mb-3 rounded-xl border p-4"><div className="flex justify-between"><b className="text-sm">{r.name}</b><span className="text-[10px] text-slate-400">{r.is_active?"Activa":"Inactiva"}</span></div>{sessions.filter(s=>s.register_id===r.id&&s.status==="open").map(s=><div key={s.id} className="mt-3 rounded-lg bg-emerald-50 p-3"><p className="text-xs font-bold text-emerald-800">Turno abierto · Fondo {money(s.opening_cash_dop)}</p><button onClick={()=>closeCash(s.id)} className="mt-2 rounded-lg bg-emerald-800 px-3 py-2 text-[10px] font-bold text-white">Cerrar y hacer arqueo</button></div>)}{!sessions.some(s=>s.register_id===r.id&&s.status==="open")&&<div className="mt-3 flex flex-wrap items-center gap-2"><input aria-label="Fondo inicial" className="w-28 rounded-lg border px-2 py-2 text-xs" type="number" value={cashForm.opening} onChange={e=>setCashForm({...cashForm,opening:e.target.value})}/><button onClick={()=>openCash(r.id)} className="rounded-lg bg-[#172c55] px-3 py-2 text-[10px] font-bold text-white">Abrir turno</button></div>}</div>)}{!registers.length&&<p className="text-xs text-slate-400">Crea una caja para comenzar.</p>}</section><form onSubmit={createRegister} className={card+" h-fit space-y-3"}><h3 className="font-black">Crear caja</h3><Field label="Nombre de caja"><input required className={input} value={cashForm.name} onChange={e=>setCashForm({...cashForm,name:e.target.value})}/></Field><button className={btn+" w-full"}><Plus size={14}/> Crear caja</button><p className="text-[10px] leading-4 text-slate-400">Las ventas en efectivo registradas en el POS se reflejan en el turno abierto.</p></form></div>}
 {tab==="locations"&&<div className="grid gap-5 xl:grid-cols-[1fr_350px]"><section className={card}><h2 className="font-black">Sucursales y puntos de venta</h2>{locations.map(l=><div key={l.id} className="flex flex-wrap items-center justify-between gap-2 border-b py-3 text-xs"><div><b>{l.name}</b><p className="text-[10px] text-slate-400">{l.address||"Sin dirección"} · {l.phone||"Sin teléfono"}</p></div>{l.is_default&&<span className="rounded-full bg-emerald-50 px-3 py-1 text-[10px] font-bold text-emerald-700">Principal</span>}</div>)}{!locations.length&&<p className="py-6 text-xs text-slate-400">Aún no has creado sucursales.</p>}</section><form onSubmit={saveLocation} className={card+" h-fit space-y-3"}><h3 className="font-black">Agregar sucursal</h3><Field label="Nombre"><input required className={input} value={locationForm.name} onChange={e=>setLocationForm({...locationForm,name:e.target.value})}/></Field><Field label="Dirección"><input className={input} value={locationForm.address} onChange={e=>setLocationForm({...locationForm,address:e.target.value})}/></Field><Field label="Teléfono"><input className={input} value={locationForm.phone} onChange={e=>setLocationForm({...locationForm,phone:e.target.value})}/></Field><button className={btn+" w-full"}><Plus size={14}/> Guardar sucursal</button></form></div>}
 {tab==="invoices"&&<div className="space-y-5"><section className={card}><h2 className="font-black">Comprobantes de venta</h2><p className="mt-1 text-xs text-slate-500">Los documentos creados hasta ahora son recibos internos, no e-CF autorizados por DGII.</p>{invoices.map(i=><div key={i.id} className="flex flex-wrap justify-between gap-2 border-b py-3 text-xs"><div><b>Recibo interno #{i.invoice_number}</b><p className="text-[10px] text-slate-400">{new Date(i.created_at).toLocaleString("es-DO")} · {i.fiscal_status}</p></div><b>{money(i.totals_snapshot?.total_dop)}</b></div>)}</section><section className={card}><h3 className="font-black">Bolsas de comprobantes electrónicos</h3><p className="mt-2 text-xs leading-5 text-slate-500">El saldo prepago y la emisión e-CF se habilitarán después de integrar un proveedor de servicios de facturación electrónica autorizado y completar las pruebas fiscales. No se realizan cobros en esta pantalla.</p><div className="mt-3 rounded-xl bg-amber-50 p-3 text-xs text-amber-800">Estado fiscal: no configurado. Los recibos internos no sustituyen un comprobante fiscal electrónico.</div></section></div>}
 {tab==="settings"&&<div className="grid gap-5 xl:grid-cols-2"><section className={card}><h2 className="font-black">Datos del comercio</h2><div className="mt-4 space-y-3 text-xs"><p><span className="text-slate-400">Nombre:</span> {merchant.store_name}</p><p><span className="text-slate-400">Teléfono:</span> {merchant.phone||"Sin registrar"}</p><p><span className="text-slate-400">Dirección:</span> {merchant.address||"Sin registrar"}</p><p><span className="text-slate-400">Estado:</span> {merchant.status}</p><p><span className="text-slate-400">Enlace:</span> /market/{merchant.slug}</p></div></section><section className={card}><h2 className="font-black">Configuración fiscal</h2><p className="mt-2 text-xs leading-5 text-slate-500">Completa nombre legal, RNC y dirección fiscal para preparar la habilitación de e-CF. La emisión real requiere un PSFE autorizado o la certificación correspondiente.</p><button onClick={()=>setTab("invoices")} className={btn+" mt-4"}>Ir a facturación</button></section></div>}
 <footer className="mt-8 border-t border-slate-200 pt-5 text-[9px] text-slate-400">Panel de gestión de comercios · Importes en pesos dominicanos · Datos protegidos por permisos del comercio.</footer>
 </main></section></div></div>;
}
